function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 1000) return 'nums needs 1 to 1000 arrays.';
  let total = 0;
  for (const row of nums) {
    if (!Array.isArray(row) || row.length === 0) return 'Every inner array must be non-empty.';
    total += row.length;
    if (row.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value is an integer from 1 to 1000.';
    if (new Set(row).size !== row.length) return 'Values inside one array must be distinct.';
  }
  if (total > 1000) return 'All arrays together hold at most 1000 values.';
  return null;
}

