function generate(rand, size) {
  const pick = (pool, k) => {
    const copy = [...pool];
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy.slice(0, k);
  };
  if (size === 'small') {
    const maxValue = 2 + Math.floor(rand() * 8);
    const pool = Array.from({ length: maxValue }, (_, i) => i + 1);
    const rows = 1 + Math.floor(rand() * 4);
    return [Array.from({ length: rows }, () => pick(pool, 1 + Math.floor(rand() * maxValue)))];
  }
  const rows = 2 + Math.floor(rand() * 6);
  const per = Math.floor(1000 / rows);
  const pool = Array.from({ length: 1000 }, (_, i) => i + 1);
  const shared = pick(pool, Math.floor(per / 2));
  const rest = pool.filter(v => !shared.includes(v));
  return [Array.from({ length: rows }, () => pick([...shared, ...pick(rest, per - shared.length)], per))];
}
